<?phprequire_once __DIR__.'/config/auth.php';$pdo=db();$pdo->exec(file_get_contents(__DIR__.'/sql/schema.sql'));if((int)$pdo->query('SELECT COUNT(*) FROM couple_users')->fetchColumn()>0){header('Location:/login-casal.php');exit;}$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$confirm=$_POST['confirm']??'';if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8||$pass!==$confirm)$err='Revise os dados. A senha deve ter ao menos 8 caracteres.';else{try{$s=$pdo->prepare("INSERT INTO couple_users(name,email,password) VALUES(:n,:e,:p) RETURNING id,name,email,status");$s->execute([':n'=>$name,':e'=>$email,':p'=>password_hash($pass,PASSWORD_DEFAULT)]);$u=$s->fetch();require_once __DIR__.'/config/seed.php';seed_couple($pdo,(int)$u['id']);issue_cookie($u);header('Location:/casal.php');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err='A conta foi criada, mas houve falha ao importar o conteúdo inicial. Entre novamente pelo Login Casal para o sistema concluir a importação automaticamente. Detalhe: '.$e->getMessage();}}}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Configurar Login Casal</title><style>body{margin:0;background:#0b0b0b;color:#fff;font-family:Arial,sans-serif}.box{min-height:100vh;display:grid;place-items:center;padding:20px}.card{width:min(450px,100%);padding:30px;background:#181818;border-radius:20px}.card h1{font-size:28px}.card input{display:block;width:100%;box-sizing:border-box;margin:7px 0 16px;padding:13px;background:#242424;border:1px solid #555;border-radius:8px;color:#fff;font-size:16px}.card button{width:100%;padding:14px;border:0;border-radius:999px;background:#1ed760;font-weight:800}.err{background:#4a1919;padding:10px}</style></head><body><main class="box"><form class="card" method="post"><h1>Primeiro acesso do casal ♥</h1><p>Crie o usuário que poderá editar o site.</p><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><?php if($err):?><div class="err"><?=htmlspecialchars($err)?></div><?php endif;?><label>Nome</label><input name="name" required><label>E-mail</label><input type="email" name="email" required><label>Senha</label><input type="password" name="password" minlength="8" required><label>Confirmar senha</label><input type="password" name="confirm" minlength="8" required><button>Criar acesso e importar conteúdo atual</button></form></main></body></html>